const SHIFTS = {
  MORNING: { name: 'Morning', startTime: '06:00' },
  EVENING: { name: 'Evening', startTime: '14:00' },
  NIGHT: { name: 'Night', startTime: '22:00' },
  FREE: { name: 'Free', startTime: '-' }
};

function getWeekNumber(date) {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  // Thursday in current week decides the year
  d.setDate(d.getDate() + 3 - (d.getDay() + 6) % 7);
  // January 4 is always in week 1
  const week1 = new Date(d.getFullYear(), 0, 4);
  // Adjust to Thursday in week 1 and count number of weeks from date to week1
  return 1 + Math.round(((d.getTime() - week1.getTime()) / 86400000 - 3 + (week1.getDay() + 6) % 7) / 7);
}

function getShiftRotation(date) {
  const year = date.getFullYear();
  const weekNumber = getWeekNumber(date);
  
  // Only process for 2025 and beyond
  if (year < 2025) return null;
  
  // Calculate weeks since start of 2025
  const weeksFrom2025 = ((year - 2025) * 52) + weekNumber;
  const rotationCycle = (weeksFrom2025 - 1) % 3;

  // Check if it's Saturday
  const dayOfWeek = date.getDay();
  if (dayOfWeek === 6) {
    return {
      A: SHIFTS.FREE,
      B: SHIFTS.FREE,
      C: SHIFTS.FREE
    };
  }

  // For Sunday
  if (dayOfWeek === 0) {
    // Only the team about to start night shifts works on Sunday
    const sundayPattern = {
      0: { A: SHIFTS.NIGHT, B: SHIFTS.FREE, C: SHIFTS.FREE },    // B starts night shifts
      1: { A: SHIFTS.FREE, B: SHIFTS.FREE, C: SHIFTS.NIGHT },    // A starts night shifts
      2: { A: SHIFTS.FREE, B: SHIFTS.NIGHT, C: SHIFTS.FREE }     // C starts night shifts
    };
    return sundayPattern[rotationCycle];
  }

  // Weekday patterns - each team stays on the same shift for the whole week
  const shiftPatterns = {
    0: { A: SHIFTS.MORNING, B: SHIFTS.NIGHT, C: SHIFTS.EVENING },   // Week 1
    1: { A: SHIFTS.NIGHT, B: SHIFTS.EVENING, C: SHIFTS.MORNING },   // Week 2
    2: { A: SHIFTS.EVENING, B: SHIFTS.MORNING, C: SHIFTS.NIGHT }    // Week 3
  };

  return shiftPatterns[rotationCycle];
}

function getCurrentShift(team) {
  const now = new Date();
  const currentRotation = getShiftRotation(now);
  
  if (!currentRotation || !team) return null;
  
  return currentRotation[team];
}

function debugShiftRotation() {
  const startDate = new Date(2025, 0, 1);  // Jan 1, 2025
  const endDate = new Date(2025, 1, 28);   // Feb 28, 2025
  const teams = ['A', 'B', 'C'];
  
  console.log('=== Shift Rotation Debug Log ===');
  console.log('Period: January-February 2025\n');

  for (let currentDate = new Date(startDate); currentDate <= endDate; currentDate.setDate(currentDate.getDate() + 1)) {
    const rotation = getShiftRotation(currentDate);
    const dayName = currentDate.toLocaleDateString('en-US', { weekday: 'long' });
    const dateStr = currentDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
    
    console.log(`${dateStr} (${dayName})`);
    teams.forEach(team => {
      const shift = rotation ? rotation[team].name : 'N/A';
      console.log(`  Team ${team}: ${shift}`);
    });
    console.log('');
  }
}

export { SHIFTS, getShiftRotation, getCurrentShift }; 