import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { Menu } from '@headlessui/react';
import { AccountCircle } from '@mui/icons-material';
import MenuIcon from '@mui/icons-material/Menu';
import CloseIcon from '@mui/icons-material/Close';

function Navbar() {
  const { currentUser, isAdmin, logout } = useAuth();
  const navigate = useNavigate();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const handleLogout = async () => {
    try {
      await logout();
      navigate('/login');
    } catch (error) {
      console.error('Failed to log out:', error);
    }
  };

  return (
    <nav className="bg-white dark:bg-dark-800 shadow-lg">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-16">
          <div className="flex items-center">
            <Link to="/" className="flex-shrink-0 flex items-center">
              <img
                src={process.env.PUBLIC_URL + '/icon.jpg'}
                alt="Logo"
                className="navbar-icon"
              />
            </Link>

            {/* Desktop Menu */}
            {currentUser && (
              <div className="hidden md:ml-6 md:flex md:space-x-4">
                <Link 
                  to="/"
                  className="px-3 py-2 rounded-md text-sm font-medium
                    text-gray-700 dark:text-gray-200 hover:text-primary-600
                    dark:hover:text-primary-400 hover:bg-gray-50
                    dark:hover:bg-dark-700"
                >
                  Timer
                </Link>
                <Link 
                  to="/reports"
                  className="px-3 py-2 rounded-md text-sm font-medium
                    text-gray-700 dark:text-gray-200 hover:text-primary-600
                    dark:hover:text-primary-400 hover:bg-gray-50
                    dark:hover:bg-dark-700"
                >
                  Reports
                </Link>
                <Link 
                  to="/calendar"
                  className="px-3 py-2 rounded-md text-sm font-medium
                    text-gray-700 dark:text-gray-200 hover:text-primary-600
                    dark:hover:text-primary-400 hover:bg-gray-50
                    dark:hover:bg-dark-700"
                >
                  Calendar
                </Link>
                {isAdmin && (
                  <Link 
                    to="/admin"
                    className="px-3 py-2 rounded-md text-sm font-medium
                      text-gray-700 dark:text-gray-200 hover:text-primary-600
                      dark:hover:text-primary-400 hover:bg-gray-50
                      dark:hover:bg-dark-700"
                  >
                    Admin
                  </Link>
                )}
              </div>
            )}
          </div>

          <div className="flex items-center space-x-2">
            {/* Mobile menu button */}
            {currentUser && (
              <button
                onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
                className="md:hidden p-2 rounded-md text-gray-700 dark:text-gray-200
                  hover:bg-gray-100 dark:hover:bg-dark-700 focus:outline-none"
              >
                {isMobileMenuOpen ? (
                  <CloseIcon className="h-6 w-6" />
                ) : (
                  <MenuIcon className="h-6 w-6" />
                )}
              </button>
            )}

            {/* User menu */}
            {currentUser && (
              <Menu as="div" className="relative">
                <Menu.Button className="p-1 rounded-full hover:bg-gray-100 
                  dark:hover:bg-dark-700 focus:outline-none focus:ring-2 
                  focus:ring-primary-500 dark:focus:ring-primary-400">
                  <AccountCircle className="h-6 w-6 text-gray-700 dark:text-gray-200" />
                </Menu.Button>

                <Menu.Items className="absolute right-0 mt-2 w-48 rounded-md shadow-lg 
                  bg-white dark:bg-dark-800 ring-1 ring-black ring-opacity-5 
                  divide-y divide-gray-100 dark:divide-dark-700 z-50">
                  <div className="py-1">
                    <Menu.Item>
                      {({ active }) => (
                        <Link
                          to="/settings"
                          className={`${
                            active ? 'bg-gray-100 dark:bg-dark-700' : ''
                          } block px-4 py-2 text-sm text-gray-700 dark:text-gray-200`}
                        >
                          Settings
                        </Link>
                      )}
                    </Menu.Item>
                    <Menu.Item>
                      {({ active }) => (
                        <button
                          onClick={handleLogout}
                          className={`${
                            active ? 'bg-gray-100 dark:bg-dark-700' : ''
                          } block w-full text-left px-4 py-2 text-sm text-gray-700 
                          dark:text-gray-200`}
                        >
                          Logout
                        </button>
                      )}
                    </Menu.Item>
                  </div>
                </Menu.Items>
              </Menu>
            )}
          </div>
        </div>
      </div>

      {/* Mobile menu */}
      {currentUser && (
        <div className={`${isMobileMenuOpen ? 'block' : 'hidden'} md:hidden`}>
          <div className="px-2 pt-2 pb-3 space-y-1 bg-white dark:bg-dark-800 
            shadow-lg border-t dark:border-dark-700">
            <Link
              to="/"
              className="block px-3 py-2 rounded-md text-base font-medium
                text-gray-700 dark:text-gray-200 hover:text-primary-600
                dark:hover:text-primary-400 hover:bg-gray-50
                dark:hover:bg-dark-700"
              onClick={() => setIsMobileMenuOpen(false)}
            >
              Timer
            </Link>
            <Link
              to="/reports"
              className="block px-3 py-2 rounded-md text-base font-medium
                text-gray-700 dark:text-gray-200 hover:text-primary-600
                dark:hover:text-primary-400 hover:bg-gray-50
                dark:hover:bg-dark-700"
              onClick={() => setIsMobileMenuOpen(false)}
            >
              Reports
            </Link>
            <Link
              to="/calendar"
              className="block px-3 py-2 rounded-md text-base font-medium
                text-gray-700 dark:text-gray-200 hover:text-primary-600
                dark:hover:text-primary-400 hover:bg-gray-50
                dark:hover:bg-dark-700"
              onClick={() => setIsMobileMenuOpen(false)}
            >
              Calendar
            </Link>
            {isAdmin && (
              <Link
                to="/admin"
                className="block px-3 py-2 rounded-md text-base font-medium
                  text-gray-700 dark:text-gray-200 hover:text-primary-600
                  dark:hover:text-primary-400 hover:bg-gray-50
                  dark:hover:bg-dark-700"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                Admin
              </Link>
            )}
          </div>
        </div>
      )}
    </nav>
  );
}

export default Navbar; 